if (($json.exitCode ?? 0) !== 0) throw new Error('BLOCKED: reporter failed');
const stdout=String($json.stdout||'').trim();
const lines=stdout.split(/\r?\n/);
const metadata=[];
while(lines.length && lines[lines.length-1].trim().startsWith('{')) { try { metadata.unshift(JSON.parse(lines.pop())); } catch { break; } }
const report=lines.join('\n').trim();
if(!(/^(?:\*\*)?【(?:OKX模拟盘|量化风险报告)/).test(report) || !report.includes('不执行交易')) throw new Error('BLOCKED: invalid report envelope');
return [{json:{report,metadata,collector_stderr:String($json.stderr||''),position_source:report.includes('可能过期')?'cache':'realtime',fail_closed:true}}];

const m=$json.report.match(/持仓：([^，\n]+)/);
const instrument=m?.[1]?.trim()||null;
return [{json:{...$json,instrument,fixed_btc:false,position_missing:!instrument}}];

const text=String($json.report ?? $json['报错'] ?? '').trim();
if(!text) throw new Error('BLOCKED: report field missing');
const out={};
for(const p of [5,10,20,60]) { const m=text.match(new RegExp('MA'+p+'\s*[=：:]\s*([^；\n]+)')); if(!m) throw new Error('BLOCKED: MA'+p+' missing'); out['ma'+p]=m[1].trim(); }
return [{json:{...$json,report:text,moving_averages:out}}];

const text=$json.report;
const m1272=text.match(/Fib 1\.272[=：]([^；\n]+)/); const m1618=text.match(/Fib 1\.618[=：]([^；\n]+)/);
const fibLine=text.match(/Fib参考[^\n]*/)?.[0]||''; const invalid=/摆动不足|无效|N\/A/.test(fibLine);
if((!m1272||!m1618) && !invalid) throw new Error('BLOCKED: Fib evidence incomplete');
return [{json:{...$json,fib:{fib_1272:m1272?.[1]?.trim()??null,fib_1618:m1618?.[1]?.trim()??null,valid:!invalid}}}];

const m=$json.report.match(/新闻(?:状态|摘要)：([^\n]+)/);
const fallback=$json.report.match(/无有效新鲜新闻[^\n]*传入news_summary为([^，。]+)/);
if(!m && !fallback) throw new Error('BLOCKED: news status missing');
return [{json:{...$json,news_summary:(m?.[1]||fallback?.[1]).trim(),news_credential_boundary:'inside-readonly-entry'}}];

const report=$json.report;
const risk=report.match(/风险等级：([^\n]+)/)?.[1]?.trim()??'未知';
const recommendation=report.match(/建议：([^\n]+)/)?.[1]?.trim()??'仅观察';
const decision=$json.metadata.find(x=>x&&x.decision_id)||null;
return [{json:{...$json,risk_analysis:{risk_level:risk,recommendation,decision},advisory_only:true}}];

const line=$json.report.match(/止损校验：([^\n]+)/)?.[1]?.trim();
const stop=$json.report.match(/止损保护(?:建议|告警)：([^\n]+)/)?.[1]?.trim();
if(!line||!stop) throw new Error('BLOCKED: stop validation absent');
return [{json:{...$json,stop_validation:{result:line,stop_loss:stop,independent:true}}}];

const line=$json.report.match(/止盈校验：([^\n]+)/)?.[1]?.trim()||$json.report.match(/止盈建议：([^\n]+)/)?.[1]?.trim();
if(!line) throw new Error('BLOCKED: take-profit validation absent');
return [{json:{...$json,take_profit_validation:{result:line,fib_valid:$json.fib.valid}}}];

const text=String($json.text||'');
const required=['持仓：','风险等级：','止损','MA5','Fib 1.272','新闻','不执行交易'];
for(const field of required) if(!text.includes(field)) throw new Error('BLOCKED: missing '+field);
if(/OKX实盘|执行模式：live|\/api\/v5\/trade\//.test(text)) throw new Error('BLOCKED: non-paper output');
const telegramText=text.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\*\*([\s\S]*?)\*\*/g,'<b>$1</b>');
return [{json:{...$json,text,telegram_text:telegramText,paper_only_validated:true}}];

const metadata=Array.isArray($json.metadata)?$json.metadata:[];
const envelope=metadata.find(value=>value&&value.protection_request)?.protection_request;
if(!envelope) throw new Error('BLOCKED: realtime dynamic TP/SL envelope missing');
if(envelope.paper_only!==true||envelope.trading_mode!=='demo'||envelope.source!=='live_reporter') throw new Error('BLOCKED: invalid protection envelope');
return [{json:{...$json,protection_request:envelope}}];

const bridge=$json;
if(bridge.status!=='OK') throw new Error('BLOCKED: protection bridge '+String(bridge.status||'unknown'));
const original=$("报告字段与paper-only校验").first().json;
const envelope=$("提取动态TP SL保护信封").first().json.protection_request;
if(!envelope) throw new Error('BLOCKED: protection envelope not retained');
return [{json:{...original,protection_request:envelope,protection_result:bridge}}];
